// Definition of the function signature
void print_args(const char *fmt, ...) {
    va_list args;

    // Initialize va_list
    va_start(args, fmt);

    // Core Action: Print using collected arguments
    vprintf(fmt, args); 

    // Clean up
    va_end(args);
}
// Use: print_args("Number: %d", 42);
// Requires: stdio.h, stdarg.h (conceptual)
